320	            setExistingResumes={setExistingResumes}
321	            onJobCreated={handleJobCreated}
322	            onAuthRequired={() => setAuthOpen(true)}
323	            isAuthenticated={!!user}
324	            pastJobs={pastJobs}
325	            onJobUpdated={handleJobUpdated}
326	          />
327	        )}
328	      </SidebarInset>
329	
330	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
331	    </SidebarProvider>
332	  );
333	};
334	
335	export default Index;
