17	export interface PastJob {
18	  id: string;
19	  title: string | null;
20	  job_description: string;
21	  status: string;
22	  created_at: string;
23	  resume_count: number;
24	  jd_analysis_json: any;
25	  dynamic_weights_json: Record<string, number> | null;
26	  inbox_email: string | null;
27	}
28	
29	export interface Result {
30	  id: string;
31	  resume_id: string;
32	  overall_score: number;
33	  missing_skills: string[];
34	  summary: string | null;
35	  interview_questions: any;
36	  filename: string;
37	  file_path: string | null;
38	  candidate_name: string | null;
39	  candidate_email?: string | null;
40	  candidate_phone?: string | null;
41	  candidate_location?: string | null;
42	  // Dynamic scoring fields
43	  hard_fit?: boolean;
44	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
45	  confidence?: number;
46	  strengths_json?: string[];
47	  gaps_json?: string[];
48	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
49	  matched_must_haves?: string[];
50	  missing_must_haves?: string[];
51	  scoring_version?: string;
52	  pending?: boolean;
53	  parsed_json?: any;
54	}
55	
56	export interface ExistingResume {
57	  id: string;
58	  filename: string;
59	  file_path: string | null;
60	  candidate_name: string | null;
61	  created_at: string;
62	}
