64	const Index = () => {
65	  const { user, profile } = useAuth();
66	  const [searchParams, setSearchParams] = useSearchParams();
67	
68	  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
69	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
70	  const [showDashboard, setShowDashboard] = useState(true);
71	  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
72	  const [results, setResults] = useState<Result[]>([]);
73	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
74	  const [authOpen, setAuthOpen] = useState(false);
75	
76	  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
77	
78	  const fetchPastJobs = useCallback(async () => {
79	    if (!user) return;
80	    setLoadingPastJobs(true);
81	    try {
82	      const { data: jobs } = await supabase
83	        .from("jobs")
84	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
85	        .eq("user_id", user.id)
86	        .order("created_at", { ascending: false })
87	        .limit(50);
88	      if (jobs) {
89	        setPastJobs(jobs.map((j: any) => ({
90	          id: j.id,
91	          title: j.title,
92	          job_description: j.job_description,
93	          status: j.status,
94	          created_at: j.created_at,
95	          resume_count: j.resumes?.[0]?.count ?? 0,
96	          jd_analysis_json: j.jd_analysis_json,
97	          dynamic_weights_json: j.dynamic_weights_json,
98	          inbox_email: j.inbox_email ?? null,
99	        })));
100	      }
101	    } catch (err) {
102	      toast.error("Failed to load jobs");
103	    } finally {
104	      setLoadingPastJobs(false);
105	    }
106	  }, [user]);
107	
108	  useEffect(() => {
109	    fetchPastJobs();
110	  }, [fetchPastJobs]);
111	
112	  // Handle URL params for deep linking from My Jobs page
113	  useEffect(() => {
114	    const jobParam = searchParams.get("job");
115	    const newParam = searchParams.get("new");
116	
117	    if (jobParam && user) {
118	      loadJobData(jobParam);
119	      setSearchParams({}, { replace: true });
120	    } else if (newParam && user) {
121	      handleNewJob();
122	      setSearchParams({}, { replace: true });
123	    }
124	    // eslint-disable-next-line react-hooks/exhaustive-deps
125	  }, [searchParams, user]);
126	
127	  const loadJobData = async (jobId: string) => {
128	    setSelectedJobId(jobId);
129	    setShowDashboard(false);
130	    try {
131	      const [resumesRes, resumeListRes] = await Promise.all([
132	        supabase
133	          .from("resumes")
134	          .select("id, filename, file_path, candidate_name, created_at")
135	          .eq("job_id", jobId)
136	          .order("created_at", { ascending: false }),
137	        supabase
138	          .from("resumes")
139	          .select("id, filename, file_path, candidate_name, parsed_json")
140	          .eq("job_id", jobId),
141	      ]);
142	
143	      const resumes = resumesRes.data ?? [];
144	      setExistingResumes(resumes);
145	
146	      const resumeData = (resumeListRes.data ?? []) as Array<{
147	        id: string;
148	        filename: string;
149	        file_path: string | null;
150	        candidate_name: string | null;
151	        parsed_json?: any;
152	      }>;
153	      if (resumeData.length === 0) {
154	        setResults([]);
155	        return;
156	      }
157	
158	      const resumeIds = resumeData.map((r) => r.id);
159	      const { data: resultData } = await supabase
160	        .from("results")
161	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
162	        .in("resume_id", resumeIds);
163	
164	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
165	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
166	        const resume = resumeMap.get(r.resume_id);
167	        const parsed = resume?.parsed_json as any;
168	        return {
169	          ...r,
170	          overall_score: r.overall_score ?? 0,
171	          missing_skills: r.missing_skills ?? [],
172	          filename: resume?.filename ?? "Unknown",
173	          file_path: resume?.file_path ?? null,
174	          candidate_name: resume?.candidate_name ?? null,
175	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
176	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
177	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
178	          parsed_json: resume?.parsed_json ?? null,
179	        };
180	      });
181	      // Deduplicate by resume_id — keep highest scoring result per resume
182	      const deduped = new Map<string, Result>();
183	      for (const r of allMerged) {
184	        const existing = deduped.get(r.resume_id);
185	        if (!existing || r.overall_score > existing.overall_score) {
186	          deduped.set(r.resume_id, r);
187	        }
188	      }
189	      const merged = Array.from(deduped.values());
190	      merged.sort((a, b) => b.overall_score - a.overall_score);
191	      setResults(merged);
192	    } catch (err) {
193	      toast.error("Failed to load job data");
194	    }
