65	function getDisplayTitle(job: PastJob): string {
66	  if (job.title) return job.title;
67	  const firstLine = job.job_description.trim().split("\n")[0].trim();
68	  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
69	}
