import { useState, useMemo } from "react";
import { cn } from "@/lib/utils";
import { Briefcase, Home, Plus, Megaphone, Settings, CreditCard, Search, FileText, Clock, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
  SidebarInput,
} from "@/components/ui/sidebar";
import { useNavigate } from "react-router-dom";

interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
}

interface JobSidebarProps {
  pastJobs?: PastJob[];
  selectedJobId: string | null;
  showDashboard?: boolean;
  showMyJobs?: boolean;
  loadingPastJobs?: boolean;
  onSelectJob?: (jobId: string) => void;
