        {/* Job list — only on My Jobs / Job Detail views */}
        {showJobList && isAuthenticated && (
          <>
            <SidebarSeparator />
            <SidebarGroup className="flex-1">
              <SidebarGroupLabel className="w-full flex items-center justify-between">
                <span>Jobs</span>
                <span className="text-[11px] text-muted-foreground/50 tabular-nums font-normal">
                  {search ? filteredJobs.length : pastJobs.length}
                </span>
              </SidebarGroupLabel>
              <SidebarGroupContent className="space-y-2">
                {/* Search + New Job */}
                <div className="px-2 space-y-2">
                  <Button
                    size="sm"
                    className="w-full gap-1.5"
                    onClick={() => {
                      if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; }
                      onNewJob();
                    }}
                  >
                    <Plus className="h-3.5 w-3.5" /> New Job
                  </Button>
                  <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
                    <SidebarInput
                      placeholder="Search jobs…"
                      value={search}
                      onChange={(e) => setSearch(e.target.value)}
                      className="pl-8 pr-7"
                    />
                    {search && (
                      <button
                        onClick={() => setSearch("")}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                        aria-label="Clear search"
                      >
                        <X className="h-3.5 w-3.5" />
                      </button>
                    )}
                  </div>
                </div>

                {/* Job cards */}
                {loadingPastJobs ? (
                  <div className="space-y-1.5 px-2">
                    {[0, 1, 2].map((i) => (
                      <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2">
                        <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
                        <div className="flex items-center justify-between">
                          <Skeleton className="h-3 w-16 bg-sidebar-accent" />
                          <Skeleton className="h-3 w-20 bg-sidebar-accent" />
                        </div>
                      </div>
                    ))}
                  </div>
                ) : filteredJobs.length === 0 ? (
                  <p className="text-xs text-muted-foreground px-4 py-4 text-center">
                    {search ? "No matching jobs." : "No jobs yet."}
                  </p>
                ) : (
                  <SidebarMenu className="space-y-1 px-2">
                    {filteredJobs.map((job) => {
                      const isActive = selectedJobId === job.id;
                      return (
                        <SidebarMenuItem key={job.id}>
                          <SidebarMenuButton
                            isActive={isActive}
                            onClick={() => onSelectJob?.(job.id)}
                            className={cn(
                              "flex flex-col items-start gap-1.5 h-auto py-2.5 px-3",
                              "rounded-lg border transition-colors",
                              isActive
                                ? "border-l-2 border-l-primary bg-sidebar-accent"
                                : "border-transparent hover:bg-sidebar-accent/50"
                            )}
                          >
                            <div className="flex items-center justify-between w-full gap-2">
                              <span className="text-sm font-medium leading-snug line-clamp-2 flex-1">
                                {getDisplayTitle(job)}
                              </span>
                              <Badge variant={statusVariant(job.status)} className="text-[10px] px-1.5 py-0 h-4 shrink-0">
                                {job.status === "completed" ? "Done" : job.status.charAt(0).toUpperCase() + job.status.slice(1)}
                              </Badge>
                            </div>
                            <div className="flex items-center gap-3 w-full text-[11px] text-muted-foreground">
                              <span className="flex items-center gap-1">
                                <FileText className="h-2.5 w-2.5" />
                                {job.resume_count}
                              </span>
                              <span className="flex items-center gap-1 ml-auto">
                                <Clock className="h-2.5 w-2.5" />
                                {format(new Date(job.created_at), "MMM d")}
                              </span>
                            </div>
                          </SidebarMenuButton>
                        </SidebarMenuItem>
                      );
                    })}
                  </SidebarMenu>
                )}
              </SidebarGroupContent>
            </SidebarGroup>
          </>
        )}

        {/* New Job CTA — show only when job list is hidden */}
        {!showJobList && (
          <>
            <SidebarSeparator />
            <SidebarGroup>
              <SidebarGroupContent>
                <div className="px-2">
                  <Button
                    className="w-full gap-1.5"
                    onClick={() => {
                      if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; }
                      onNewJob();
                    }}
                  >
                    <Plus className="h-4 w-4" /> New Job
                  </Button>
                </div>
              </SidebarGroupContent>
            </SidebarGroup>
          </>
        )}
      </SidebarContent>

      <SidebarFooter className="p-3 space-y-2">
        <SidebarSeparator />
        <div className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2.5">
          <div className="flex items-center gap-2">
            <Megaphone className="h-3.5 w-3.5 text-sidebar-primary" />
            <span className="text-xs font-semibold text-sidebar-foreground">What's new</span>
          </div>
          <div className="flex gap-2">
            <a
              href="/request-feature"
              className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
            >
              Feature Request
            </a>
            <a
              href="/changelog"
              className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
            >
              Changelog
            </a>
          </div>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
};

