import React from "react";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Coins, ChevronDown, AlertTriangle, Plus, Zap, Gift, CreditCard } from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";

const WalletDropdown = () => {
  const { profile } = useAuth();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  const subCredits = profile?.subscription_credits ?? 0;
  const topCredits = profile?.topup_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + topCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const isLowCredits = totalCredits < 3;
  const hasSplitCredits = splitTotal > 0;

  // Credit usage bar segments
  const segments = hasSplitCredits
    ? [
        { label: "Monthly", value: subCredits, color: "bg-primary" },
        { label: "Top-up", value: topCredits, color: "bg-primary/60" },
        { label: "Bonus", value: bonusCredits, color: "bg-amber-400" },
      ]
    : [];

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className={cn(
            "inline-flex items-center gap-1.5 rounded-lg h-9 px-3 outline-none focus-visible:ring-2 focus-visible:ring-offset-1 transition-all text-sm font-semibold",
            isLowCredits
              ? "bg-destructive/10 text-destructive hover:bg-destructive/15 focus-visible:ring-destructive"
              : "bg-muted text-foreground hover:bg-muted/80 focus-visible:ring-ring"
          )}
        >
          {isLowCredits ? (
            <AlertTriangle className="h-4 w-4 shrink-0" />
          ) : (
            <Coins className="h-4 w-4 shrink-0 text-primary" />
          )}
          <span className="tabular-nums">{totalCredits.toLocaleString()}</span>
          <ChevronDown className={cn("h-3 w-3 text-muted-foreground transition-transform", open && "rotate-180")} />
        </button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-72 p-0">
        {/* Balance header */}
        <div className="px-4 pt-4 pb-3">
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">Credit Balance</p>
          <div className="flex items-baseline gap-2 mt-1">
            <span className="text-3xl font-bold tabular-nums text-foreground leading-none">
              {totalCredits.toLocaleString()}
            </span>
            <span className="text-xs text-muted-foreground font-medium">credits left</span>
          </div>
        </div>

        {/* Progress bar */}
        {hasSplitCredits && totalCredits > 0 && (
          <div className="px-4 pb-3">
            <div className="h-2 rounded-full bg-muted overflow-hidden flex">
              {segments.map((seg) =>
                seg.value > 0 ? (
                  <div
                    key={seg.label}
                    className={cn("h-full first:rounded-l-full last:rounded-r-full", seg.color)}
                    style={{ width: `${(seg.value / totalCredits) * 100}%` }}
                  />
                ) : null
              )}
            </div>
            <div className="flex items-center gap-3 mt-2">
              {segments.map((seg) =>
                seg.value > 0 ? (
                  <div key={seg.label} className="flex items-center gap-1.5">
                    <span className={cn("h-2 w-2 rounded-full", seg.color)} />
                    <span className="text-[10px] text-muted-foreground">
                      {seg.label} ({seg.value.toLocaleString()})
                    </span>
                  </div>
                ) : null
              )}
            </div>
          </div>
        )}

        <Separator />

        {/* Breakdown rows */}
        {hasSplitCredits && (
          <div className="px-4 py-3 space-y-2.5">
            <CreditRow icon={Zap} label="Subscription" value={subCredits} color="text-primary" />
            <CreditRow icon={CreditCard} label="Top-up" value={topCredits} color="text-emerald-500" />
            <CreditRow icon={Gift} label="Bonus" value={bonusCredits} color="text-amber-500" />
          </div>
        )}

        {/* Low credits warning */}
        {isLowCredits && (
          <>
            <Separator />
            <div className="px-4 py-2.5 bg-destructive/5">
              <p className="text-xs text-destructive font-medium">
                Running low — top up to keep ranking.
              </p>
            </div>
          </>
        )}

        {/* Explainer */}
        {hasSplitCredits && !isLowCredits && (
          <>
            <Separator />
            <div className="px-4 py-2">
              <p className="text-[10px] text-muted-foreground/70 leading-relaxed">
                Monthly credits used first. Top-up & bonus never expire.
              </p>
            </div>
          </>
        )}

        {/* Actions */}
        <Separator />
        <div className="p-2">
          <Button
            className="w-full gap-2"
            onClick={() => { setOpen(false); navigate("/billing"); }}
          >
            <Plus className="h-4 w-4" />
            Buy Credits
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

function CreditRow({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <div className="flex items-center justify-between">
      <div className="flex items-center gap-2.5">
        <Icon className={cn("h-3.5 w-3.5", color)} />
        <span className="text-sm text-foreground">{label}</span>
      </div>
      <span className="text-sm font-semibold tabular-nums text-foreground">{value.toLocaleString()}</span>
    </div>
  );
}

export default React.memo(WalletDropdown);

