            </div>
          )}
          {rankingError && (
            <div className={`rounded-lg border p-4 flex items-start gap-3 animate-fade-in ${
              rankingError.type === "credits" ? "border-destructive/40 bg-destructive/5" : "border-border bg-muted/50"
            }`}>
              <AlertTriangle className={`h-5 w-5 mt-0.5 shrink-0 ${rankingError.type === "credits" ? "text-destructive" : "text-muted-foreground"}`} />
              <div className="flex-1">
                <p className="text-sm font-medium">
                  {rankingError.type === "credits" ? "Not enough credits" : rankingError.type === "rate_limit" ? "Too many requests" : "Ranking failed"}
                </p>
                <p className="text-sm text-muted-foreground mt-0.5">{rankingError.message}</p>
                {rankingError.type === "credits" && (
                  <Button variant="outline" size="sm" className="mt-2 gap-1.5" asChild>
                    <Link to="/billing"><Wallet className="h-3.5 w-3.5" /> Buy Credits</Link>
                  </Button>
                )}
              </div>
            </div>
          )}
          {stuckJobDetected && (
            <div className="rounded-lg border border-amber-500/40 bg-amber-500/5 p-4 flex items-start gap-3 animate-fade-in">
              <AlertTriangle className="h-5 w-5 mt-0.5 shrink-0 text-amber-500" />
              <div className="flex-1">
                <p className="text-sm font-medium">Ranking appears stuck</p>
                <p className="text-sm text-muted-foreground mt-0.5">
                  Processing has been running for over 5 minutes. Some resumes may not have been scored.
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  className="mt-2"
                  onClick={handleRetryStuck}
                  disabled={retrying}
                >
                  {retrying ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <RefreshCw className="h-3 w-3 mr-1" />}
                  Retry unscored resumes
                </Button>
              </div>
            </div>
          )}
          {ranking && (
            <div className="space-y-2 animate-fade-in">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm text-primary font-medium">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {rankingProgress < 25 ? "Analyzing job…" : rankingProgress < 40 ? "Preparing resumes…" : rankingProgress < 60 ? "Parsing resumes…" : totalToScore > 0 ? `Scoring ${scoredCount}/${totalToScore}…` : "Scoring candidates…"}
                </div>
              </div>
              <Progress value={rankingProgress} className="h-2" aria-label={`Ranking progress: ${Math.round(rankingProgress)}%`} />
            </div>
          )}
        </div>


        {/* Pending resumes banner — prompt to rank */}
        {isExistingJob && visibleResults.some(r => r.pending) && !ranking && (() => {
          const pendingCount = visibleResults.filter(r => r.pending).length;
          return (
            <Card className="border-primary/30 bg-primary/5">
              <CardContent className="px-5 py-4 flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm font-medium text-foreground">
                    {pendingCount} new resume{pendingCount !== 1 ? "s" : ""} ready to rank
                  </p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Score and rank {pendingCount === 1 ? "this candidate" : "these candidates"} against your job description.
                  </p>
                </div>
                <Button onClick={handleRerank} className="gap-1.5 shrink-0">
                  <Zap className="h-4 w-4" /> Rank {pendingCount}
                </Button>
              </CardContent>
            </Card>
          );
        })()}

        {/* Results Table */}
        {visibleResults.length > 0 && (
          <div ref={resultsRef}>
            <Card>
              <CardHeader className="px-4 py-3 space-y-3">
                {/* Row 1: Title + stage filters */}
                <div className="flex items-center gap-2 flex-wrap">
                  <CardTitle className="text-sm font-semibold">
                    Results ({visibleResults.filter(r => !r.pending).length}{visibleResults.some(r => r.pending) ? ` scored · ${visibleResults.filter(r => r.pending).length} pending` : ""})
                  </CardTitle>
                  {nonArchivedResults.some(r => !r.pending) && (
                    <div className="flex items-center gap-1">
                      {(["applied", "screened", "interview", "offer", "hired", "rejected"] as const).map((stage) => {
                        const count = effectiveStageCounts[stage];
                        if (count === 0) return null;
                        const isActive = stageFilter === stage;
                        const colors: Record<string, string> = {
                          applied: isActive ? "bg-muted-foreground text-background" : "bg-muted text-muted-foreground hover:bg-muted-foreground/20",
                          screened: isActive ? "bg-blue-600 text-white dark:bg-blue-500" : "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 hover:bg-blue-200 dark:hover:bg-blue-900/50",
                          interview: isActive ? "bg-purple-600 text-white dark:bg-purple-500" : "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400 hover:bg-purple-200 dark:hover:bg-purple-900/50",
                          offer: isActive ? "bg-amber-600 text-white dark:bg-amber-500" : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 hover:bg-amber-200 dark:hover:bg-amber-900/50",
                          hired: isActive ? "bg-emerald-600 text-white dark:bg-emerald-500" : "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 hover:bg-emerald-200 dark:hover:bg-emerald-900/50",
                          rejected: isActive ? "bg-red-600 text-white dark:bg-red-500" : "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-900/50",
                        };
                        return (
                          <button
                            key={stage}
                            onClick={() => setStageFilter(isActive ? null : stage)}
                            className={`text-[11px] font-medium px-1.5 py-0.5 rounded transition-colors ${colors[stage]}`}
                          >
                            {count} {stage.charAt(0).toUpperCase() + stage.slice(1)}
                            {isActive && " ×"}
                          </button>
                        );
                      })}
                    </div>
                  )}
                  <div className="flex items-center gap-1.5 ml-auto">
                    {dismissedResumes.size > 0 && (
                      <Button
                        variant={showArchived ? "secondary" : "outline"}
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => setShowArchived((v) => !v)}
                      >
                        <FolderOpen className="h-3 w-3" />
                        Archived ({dismissedResumes.size})
                      </Button>
                    )}
                    {visibleResults.length > 0 && (
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => {
                          const formatCandidateNameLocal = (filename: string) => {
                            const name = filename.replace(/\.\w+$/, "");
                            if (UUID_REGEX.test(name)) return "Candidate";
                            return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
                          };
                          const rows = visibleResults.filter((r) => !r.pending).map((r, i) => {
                            const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.length : 0;
                            const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.length : 0;
                            const total = matched + missing;
                            const jdAlignment = total > 0 ? Math.round((matched / total) * 100) : 0;
                            const stage = stageMap.get(r.resume_id)?.stage ?? "applied";
                            return {
                              "Rank": i + 1,
                              "Candidate Name": r.candidate_name || formatCandidateNameLocal(r.filename),
                              "Email": r.candidate_email ?? "",
                              "Phone": r.candidate_phone ?? "",
                              "Location": r.candidate_location ?? "",
                              "Stage": stage.charAt(0).toUpperCase() + stage.slice(1),
                              "Overall Score": r.overall_score?.toFixed(0) ?? "0",
                              "Confidence": (r.confidence ?? 0).toFixed(0),
                              "Hard Fit": r.hard_fit ? "Yes" : "No",
                              "JD Alignment %": jdAlignment,
                              "Strengths": (r.strengths_json ?? []).join("; "),
                              "Gaps": (r.gaps_json ?? []).join("; "),
                              "Missing Skills": (r.missing_skills ?? []).join("; "),
                            };
                          });
                          exportToCSV(rows, selectedJob?.title || "results");
                        }}
                      >
                        <FileSpreadsheet className="h-3 w-3" />
                        Export
                      </Button>
                    )}
                    {isExistingJob && existingResumes.length > 0 && (() => {
                      const hasPending = visibleResults.some(r => r.pending);
                      const hasScored = visibleResults.some(r => !r.pending);
                      return (
                        <Button
                          variant={hasPending && !hasScored ? "default" : "outline"}
                          size="sm"
                          className="h-7 gap-1.5 text-xs"
                          disabled={ranking}
                          onClick={handleRerank}
                        >
                          {ranking ? <Loader2 className="h-3 w-3 animate-spin" /> : hasPending && !hasScored ? <Zap className="h-3 w-3" /> : <RefreshCw className="h-3 w-3" />}
                          {hasPending && !hasScored ? `Rank ${visibleResults.filter(r => r.pending).length} Resumes` : "Re-rank"}
                        </Button>
                      );
                    })()}
                  </div>
                </div>

                {/* Row 2: Selection actions — only when candidates are selected */}
                {selectedResumes.size > 0 && (
                  <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border">
                    <span className="text-xs font-medium text-foreground">{selectedResumes.size} selected</span>
                    <div className="flex items-center gap-1.5 ml-auto">
                      <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => setSelectedResumes(new Set())}>
                        Clear
                      </Button>
                      <Button variant="destructive" size="sm" className="h-7 gap-1.5 text-xs" onClick={() => setDeleteConfirm({ type: "bulk" })}>
                        <Trash2 className="h-3 w-3" /> Delete
                      </Button>
                    </div>
                  </div>
                )}
              </CardHeader>
              <CardContent className="p-0">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="sticky top-0 bg-card z-10">
                      <TableRow>
                        <TableHead className="w-10">
                          <Checkbox
                            aria-label="Select all candidates"
                            checked={visibleResults.length > 0 && visibleResults.every(r => selectedResumes.has(r.resume_id))}
                            onCheckedChange={(checked) => {
                              if (checked) setSelectedResumes(prev => new Set([...prev, ...visibleResults.map(r => r.resume_id)]));
                              else setSelectedResumes(prev => { const next = new Set(prev); visibleResults.forEach(r => next.delete(r.resume_id)); return next; });
                            }}
                          />
                        </TableHead>
                        <TableHead className="w-14 text-center">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead className="w-32">Match</TableHead>
                        <TableHead className="w-20">Strength</TableHead>
                        <TableHead className="w-36"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {ranking && visibleResults.filter(r => !r.pending).length === 0 && (
                        <>
                          {[0, 1, 2, 3, 4].map((i) => (
                            <TableRow key={`skel-${i}`} className="animate-pulse">
                              <TableCell><Skeleton className="h-4 w-4 rounded" /></TableCell>
                              <TableCell className="text-center"><Skeleton className="h-4 w-6 mx-auto rounded" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-40" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                              <TableCell><Skeleton className="h-5 w-16 rounded-full" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                            </TableRow>
                          ))}
                        </>
                      )}
                      {visibleResults.map((r, index) => (
                        <CandidateRow
                          key={r.id}
                          result={r}
                          index={index}
                          isSelected={selectedResumes.has(r.resume_id)}
                          isActive={selectedCandidateId === r.id}
                          jobId={selectedJobId}
                          jobTitle={selectedJob?.title}
                          onSelect={selectCandidate}
                          onToggleSelect={toggleSelectResume}
                          onDownload={downloadResume}
                          onDismiss={handleDismiss}
                          formatCandidateName={formatCandidateName}
                          currentStage={stageMap.get(r.resume_id)?.stage}
                          isDuplicate={duplicateResumeIds.has(r.resume_id)}
                        />
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </CardContent>
            </Card>

            {/* Archived Candidates Panel */}
            {showArchived && archivedResults.length > 0 && (
              <Card className="mt-3 border-amber-200 dark:border-amber-800">
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-base flex items-center gap-2 text-amber-700 dark:text-amber-400">
                      <Archive className="h-4 w-4" />
                      Archived Candidates ({archivedResults.length})
                    </CardTitle>
                    <button
                      onClick={() => setShowArchived(false)}
                      className="text-muted-foreground hover:text-foreground"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead className="w-14 text-center pl-4">#</TableHead>
                          <TableHead>Candidate</TableHead>
                          <TableHead className="w-32">Match</TableHead>
                          <TableHead className="w-20">Strength</TableHead>
                          <TableHead className="w-20 text-right pr-4">Restore</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {archivedResults.map((r, index) => {
                          const scoreColor = r.overall_score >= 70 ? "text-score-skills" : r.overall_score >= 40 ? "text-warning" : "text-destructive";
                          const strengthLabel = r.overall_score >= 70 ? "Strong" : r.overall_score >= 40 ? "Good" : "Weak";
                          const strengthVariant = r.overall_score >= 70 ? "success" : r.overall_score >= 40 ? "warning" : "destructive";
                          return (
                            <TableRow key={r.id} className="opacity-60 hover:opacity-100 transition-opacity">
                              <TableCell className="text-center text-sm text-muted-foreground pl-4">{index + 1}</TableCell>
                              <TableCell className="font-medium text-sm">
                                {r.candidate_name || formatCandidateName(r.filename)}
                              </TableCell>
                              <TableCell>
                                {!r.pending && (
                                  <div className="flex items-center gap-2">
                                    <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[80px]">
                                      <div
                                        className={`h-full rounded-full transition-all ${r.overall_score >= 70 ? "bg-score-skills" : r.overall_score >= 40 ? "bg-warning" : "bg-destructive"}`}
                                        style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                                      />
                                    </div>
                                    <span className={`text-sm font-semibold tabular-nums ${scoreColor}`}>{r.overall_score?.toFixed(0)}%</span>
                                  </div>
                                )}
                              </TableCell>
                              <TableCell>
                                {!r.pending && <Badge variant={strengthVariant as "success" | "warning" | "destructive"} className="text-[11px]">{strengthLabel}</Badge>}
                              </TableCell>
                              <TableCell className="text-right pr-4">
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-7 w-7 text-muted-foreground hover:text-amber-600"
                                  onClick={() => handleUnarchive(r.resume_id)}
                                  title="Restore candidate"
                                >
                                  <ArchiveRestore className="h-3.5 w-3.5" />
                                </Button>
                              </TableCell>
                            </TableRow>
                          );
                        })}
                      </TableBody>
                    </Table>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </div>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete {deleteCount} resume{deleteCount > 1 ? "s" : ""} and any associated results. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm Edit JD Warning */}
      <AlertDialog open={confirmEditJdOpen} onOpenChange={setConfirmEditJdOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Edit Job Description?</AlertDialogTitle>
            <AlertDialogDescription className="space-y-2">
              <span className="block">
                This job has <strong>{results.length} ranked candidate{results.length !== 1 ? "s" : ""}</strong>. Editing the JD will make existing scores outdated since they were based on the original description.
              </span>
              <span className="block">
                You can re-rank resumes after editing. Standard credit charges will apply for re-ranking.
              </span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => setEditingJd(true)}>
              Edit Anyway
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* JD Rewrite Dialog */}
      {jdRewriteOpen && (
        <JDRewriteDialog
          open={jdRewriteOpen}
          onOpenChange={setJdRewriteOpen}
          jobId={isExistingJob ? selectedJobId! : ""}
          originalJd={isExistingJob ? (selectedJob?.job_description ?? "") : jobDescription}
          onApply={async (newJd) => {
            setJobDescription(newJd);
            if (isExistingJob && selectedJobId) {
              try {
                await supabase.from("jobs").update({ job_description: newJd }).eq("id", selectedJobId);
                onJobUpdated?.(selectedJobId, { job_description: newJd });
                toast.success("Job description updated");
              } catch (err) {
                toast.error("Failed to save rewritten JD");
              }
            }
          }}
        />
      )}

      {/* Candidate Detail Sheet */}
      {(() => {
        const selectedResult = selectedCandidateId ? visibleResults.find((r) => r.id === selectedCandidateId) ?? null : null;
        return (
          <CandidateDetailSheet
            result={selectedResult}
            isOpen={!!selectedCandidateId && !!selectedResult}
            onClose={() => setSelectedCandidateId(null)}
            jobId={selectedJobId}
            jobTitle={selectedJob?.title}
            formatCandidateName={formatCandidateName}
            onDownload={downloadResume}
            onDismiss={handleDismiss}
            currentStage={selectedResult ? stageMap.get(selectedResult.resume_id)?.stage : undefined}
            stageUpdatedAt={selectedResult ? stageMap.get(selectedResult.resume_id)?.updated_at : undefined}
            onStageChange={handleStageChange}
          />
        );
      })()}
    </div>
  );
};

export default JobDetailView;

import React, { useState, useCallback, useEffect, useMemo } from "react";
import { useSearchParams, useLocation } from "react-router-dom";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import AppHeader from "@/components/AppHeader";
import AuthDialog from "@/components/AuthDialog";
import JobSidebar from "@/components/JobSidebar";
import JobDetailView from "@/components/JobDetailView";
import JobsOverviewCard from "@/components/JobsOverviewCard";
import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
import { format } from "date-fns";
import { toast } from "sonner";

export interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
  jd_analysis_json: any;
  dynamic_weights_json: Record<string, number> | null;
  inbox_email: string | null;
}

export interface Result {
  id: string;
  resume_id: string;
  overall_score: number;
  missing_skills: string[];
  summary: string | null;
  interview_questions: any;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  candidate_email?: string | null;
  candidate_phone?: string | null;
  candidate_location?: string | null;
  // Dynamic scoring fields
  hard_fit?: boolean;
  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
  confidence?: number;
  strengths_json?: string[];
  gaps_json?: string[];
  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
  matched_must_haves?: string[];
  missing_must_haves?: string[];
  scoring_version?: string;
  pending?: boolean;
  parsed_json?: any;
}

export interface ExistingResume {
  id: string;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  created_at: string;
}

type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";

const Index = () => {
  const { user, profile } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const location = useLocation();

  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
  const [results, setResults] = useState<Result[]>([]);
  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
  const [authOpen, setAuthOpen] = useState(false);

  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);

  const fetchPastJobs = useCallback(async () => {
    if (!user) return;
    setLoadingPastJobs(true);
    try {
      const { data: jobs } = await supabase
        .from("jobs")
        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(50);
      if (jobs) {
        setPastJobs(jobs.map((j: any) => ({
          id: j.id,
          title: j.title,
          job_description: j.job_description,
          status: j.status,
          created_at: j.created_at,
          resume_count: j.resumes?.[0]?.count ?? 0,
          jd_analysis_json: j.jd_analysis_json,
          dynamic_weights_json: j.dynamic_weights_json,
          inbox_email: j.inbox_email ?? null,
        })));
      }
    } catch (err) {
      toast.error("Failed to load jobs");
    } finally {
      setLoadingPastJobs(false);
    }
  }, [user]);

  useEffect(() => {
    fetchPastJobs();
  }, [fetchPastJobs]);

  // Sync view with route path
  useEffect(() => {
    if (location.pathname === "/jobs") {
      setView("my-jobs");
      setSelectedJobId(null);
    }
  }, [location.pathname]);

  // Handle URL params for deep linking
  useEffect(() => {
    const jobParam = searchParams.get("job");
    const newParam = searchParams.get("new");

    if (jobParam && user) {
      loadJobData(jobParam);
      setSearchParams({}, { replace: true });
    } else if (newParam && user) {
      handleNewJob();
      setSearchParams({}, { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, user]);

  const loadJobData = async (jobId: string) => {
    setSelectedJobId(jobId);
    setView("job-detail");
    try {
      // Single query for all resume data (was 2 separate queries)
      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });

      const resumeData = allResumes ?? [];
      setExistingResumes(resumeData.map((r) => ({
        id: r.id, filename: r.filename, file_path: r.file_path,
        candidate_name: r.candidate_name, created_at: r.created_at,
      })));

      if (resumeData.length === 0) {
        setResults([]);
        return;
      }

      const resumeIds = resumeData.map((r) => r.id);
      const { data: resultData } = await supabase
        .from("results")
        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
        .in("resume_id", resumeIds);

      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
        const resume = resumeMap.get(r.resume_id);
        const parsed = resume?.parsed_json as any;
        return {
          ...r,
          overall_score: r.overall_score ?? 0,
          missing_skills: r.missing_skills ?? [],
          filename: resume?.filename ?? "Unknown",
          file_path: resume?.file_path ?? null,
          candidate_name: resume?.candidate_name ?? null,
          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
          parsed_json: resume?.parsed_json ?? null,
        };
      });
      // Deduplicate by resume_id — keep highest scoring result per resume
      const deduped = new Map<string, Result>();
      for (const r of allMerged) {
        const existing = deduped.get(r.resume_id);
        if (!existing || r.overall_score > existing.overall_score) {
          deduped.set(r.resume_id, r);
        }
      }
      const merged = Array.from(deduped.values());
      merged.sort((a, b) => b.overall_score - a.overall_score);
      setResults(merged);
    } catch (err) {
      toast.error("Failed to load job data");
    }
  };

  const handleNewJob = () => {
    setSelectedJobId(null);
    setView("new-job");
    setResults([]);
    setExistingResumes([]);
  };

  const handleGoToDashboard = () => {
    setSelectedJobId(null);
    setView("dashboard");
    setResults([]);
    setExistingResumes([]);
  };

  const handleGoToMyJobs = () => {
    setSelectedJobId(null);
    setView("my-jobs");
    setResults([]);
    setExistingResumes([]);
  };

  const handleJobCreated = (job: PastJob) => {
    setPastJobs((prev) => [job, ...prev]);
    setSelectedJobId(job.id);
    loadJobData(job.id);
  };

  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
    setPastJobs((prev) =>
      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
    );
  };

  const handleDeleteJobs = async (jobIds: string[]) => {
    await supabase.from("jobs").delete().in("id", jobIds);
    setPastJobs((prev) => prev.filter((j) => !jobIds.includes(j.id)));
  };

  const requireAuth = useCallback(() => {
    if (!user) { setAuthOpen(true); return true; }
    return false;
  }, [user]);

  return (
    <SidebarProvider className="h-svh overflow-hidden">
      <JobSidebar
        pastJobs={pastJobs}
        selectedJobId={selectedJobId}
        showDashboard={view === "dashboard"}
        showMyJobs={view === "my-jobs"}
        loadingPastJobs={loadingPastJobs}
        onSelectJob={loadJobData}
        onNewJob={handleNewJob}
        onDashboard={handleGoToDashboard}
        onMyJobs={handleGoToMyJobs}
        onAuthRequired={() => setAuthOpen(true)}
        isAuthenticated={!!user}
      />

      <SidebarInset className="h-svh overflow-y-auto">
        <AppHeader />
        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
          <SidebarTrigger />
          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
        </div>

        {/* Dashboard view */}
        {view === "dashboard" && user ? (
          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
            {/* Hero Section — Greeting + Create Button */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <h1 className="text-2xl font-bold text-foreground">
                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                  Here's an overview of your hiring activity and insights.
                </p>
              </div>
              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
                <Plus className="h-4 w-4" /> Create Job
              </Button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {[
                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
              ].map((s) => (
                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
                  <CardContent className="px-5 py-4 flex items-center gap-4">
                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
                      <s.icon className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            {/* Recent Jobs */}
            {pastJobs.length > 0 && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
                    View All Jobs →
                  </button>
                </div>
                <div className="grid gap-3">
                  {pastJobs.slice(0, 5).map((job) => (
                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
                        <div className="flex items-center gap-3 min-w-0">
                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                            <Briefcase className="h-4 w-4 text-primary" />
                          </div>
                          <div className="min-w-0">
                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
                            <p className="text-xs text-muted-foreground mt-0.5">
                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center gap-3 shrink-0">
                          <Badge
                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
                            className="text-xs"
                          >
                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
                          </Badge>
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            )}

            {/* Getting started guide — show only for new users */}
            {pastJobs.length === 0 && !loadingPastJobs && (
              <Card>
                <CardContent className="px-5 py-4 space-y-3">
                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
                  <div className="space-y-2.5">
                    {[
                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
                    ].map((item) => (
                      <div key={item.step} className="flex items-start gap-3 text-sm">
                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
                        <span className="text-muted-foreground">{item.text}</span>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        ) : view === "my-jobs" && user ? (
          /* My Jobs view — full management */
          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
            {/* Breadcrumb */}
            <nav className="flex items-center gap-1.5 text-sm">
              <button
                onClick={handleGoToDashboard}
                className="inline-flex items-center gap-1 text-muted-foreground hover:text-foreground transition-colors group"
              >
                <ChevronLeft className="h-3.5 w-3.5 group-hover:-translate-x-0.5 transition-transform duration-150" />
                Dashboard
              </button>
            </nav>

            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
                <p className="text-sm text-muted-foreground mt-1">Manage all your job postings.</p>
              </div>
              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
                <Plus className="h-4 w-4" /> Create Job
              </Button>
            </div>
            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
          </div>
        ) : (
          <JobDetailView
            selectedJobId={selectedJobId}
            selectedJob={selectedJob}
            results={results}
            setResults={setResults}
            existingResumes={existingResumes}
            setExistingResumes={setExistingResumes}
            onJobCreated={handleJobCreated}
            onAuthRequired={() => setAuthOpen(true)}
            isAuthenticated={!!user}
            pastJobs={pastJobs}
            onJobUpdated={handleJobUpdated}
            onBack={handleGoToMyJobs}
          />
        )}
      </SidebarInset>

      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
    </SidebarProvider>
  );
};

export default Index;

