                    <div className="flex items-center gap-1">
                      {(["applied", "screened", "interview", "offer", "hired", "rejected"] as const).map((stage) => {
                        const count = effectiveStageCounts[stage];
                        if (count === 0) return null;
                        const isActive = stageFilter === stage;
                        const colors: Record<string, string> = {
                          applied: isActive ? "bg-muted-foreground text-background" : "bg-muted text-muted-foreground hover:bg-muted-foreground/20",
                          screened: isActive ? "bg-blue-600 text-white dark:bg-blue-500" : "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 hover:bg-blue-200 dark:hover:bg-blue-900/50",
                          interview: isActive ? "bg-purple-600 text-white dark:bg-purple-500" : "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400 hover:bg-purple-200 dark:hover:bg-purple-900/50",
                          offer: isActive ? "bg-amber-600 text-white dark:bg-amber-500" : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 hover:bg-amber-200 dark:hover:bg-amber-900/50",
                          hired: isActive ? "bg-emerald-600 text-white dark:bg-emerald-500" : "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 hover:bg-emerald-200 dark:hover:bg-emerald-900/50",
                          rejected: isActive ? "bg-red-600 text-white dark:bg-red-500" : "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-900/50",
