-- Changelog table for product updates
CREATE TABLE IF NOT EXISTS public.changelog (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  version text NOT NULL,
  title text NOT NULL,
  description text NOT NULL,
  category text NOT NULL DEFAULT 'feature',
  status text NOT NULL DEFAULT 'draft',
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.changelog ENABLE ROW LEVEL SECURITY;

-- Anyone can read published entries (public page)
CREATE POLICY "Public reads published changelogs"
  ON public.changelog FOR SELECT
  USING (status = 'published');

-- Admins can do everything
CREATE POLICY "Admins manage changelogs"
  ON public.changelog FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'::public.app_role));

CREATE INDEX IF NOT EXISTS idx_changelog_status ON public.changelog(status);
CREATE INDEX IF NOT EXISTS idx_changelog_published_at ON public.changelog(published_at DESC);

-- Add votes count and admin notes to feature_requests
ALTER TABLE public.feature_requests
  ADD COLUMN IF NOT EXISTS votes integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS admin_note text;

-- Allow ALL authenticated users to read all feature requests (public board)
DROP POLICY IF EXISTS "Users read own feature requests" ON public.feature_requests;
DROP POLICY IF EXISTS "Admins read all feature requests" ON public.feature_requests;
CREATE POLICY "Authenticated reads all feature requests"
  ON public.feature_requests FOR SELECT TO authenticated
  USING (true);

-- Votes tracking table (one vote per user per request)
CREATE TABLE IF NOT EXISTS public.feature_request_votes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  feature_request_id uuid NOT NULL REFERENCES public.feature_requests(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(feature_request_id, user_id)
);

ALTER TABLE public.feature_request_votes ENABLE ROW LEVEL SECURITY;

-- Users can insert/delete their own votes
CREATE POLICY "Users manage own votes"
  ON public.feature_request_votes FOR ALL TO authenticated
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

-- Users can see all votes (to check if they voted)
CREATE POLICY "Authenticated reads all votes"
  ON public.feature_request_votes FOR SELECT TO authenticated
  USING (true);

-- Function to toggle vote and update count atomically
CREATE OR REPLACE FUNCTION public.toggle_feature_vote(p_request_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_exists boolean;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM feature_request_votes
    WHERE feature_request_id = p_request_id AND user_id = auth.uid()
  ) INTO v_exists;

  IF v_exists THEN
    DELETE FROM feature_request_votes
    WHERE feature_request_id = p_request_id AND user_id = auth.uid();
    UPDATE feature_requests SET votes = GREATEST(0, votes - 1) WHERE id = p_request_id;
    RETURN false; -- unvoted
  ELSE
    INSERT INTO feature_request_votes (feature_request_id, user_id) VALUES (p_request_id, auth.uid());
    UPDATE feature_requests SET votes = votes + 1 WHERE id = p_request_id;
    RETURN true; -- voted
  END IF;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.toggle_feature_vote(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.toggle_feature_vote(uuid) TO authenticated;

-- Index for fast vote lookups
CREATE INDEX IF NOT EXISTS idx_feature_request_votes_user
  ON public.feature_request_votes(user_id, feature_request_id);
